-- Real-Time Travel Planner MVP schema (PostgreSQL)
-- UUIDs are generated by the application; timestamps are stored as timestamptz.

CREATE TABLE users (
    id              uuid PRIMARY KEY,
    name            text NOT NULL,
    email           text NOT NULL UNIQUE,
    preferences     jsonb NOT NULL DEFAULT '{}'::jsonb,
    push_token      text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE trips (
    id              uuid PRIMARY KEY,
    owner_id        uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    destination     text NOT NULL,
    start_date      date NOT NULL,
    end_date        date NOT NULL,
    budget          numeric(12,2) CHECK (budget IS NULL OR budget >= 0),
    currency        char(3) NOT NULL DEFAULT 'USD',
    status          text NOT NULL DEFAULT 'planning'
                    CHECK (status IN ('planning', 'active', 'completed', 'cancelled')),
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    CHECK (end_date >= start_date)
);

CREATE TABLE trip_members (
    trip_id         uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role            text NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'member')),
    joined_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (trip_id, user_id)
);

CREATE TABLE itinerary_items (
    id              uuid PRIMARY KEY,
    trip_id         uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    flight_subscription_id uuid,
    day             smallint NOT NULL CHECK (day > 0),
    start_time      time NOT NULL,
    end_time        time NOT NULL,
    place_name      text NOT NULL,
    place_id        text,
    type            text NOT NULL CHECK (type IN ('activity', 'meal', 'transfer', 'stay')),
    status          text NOT NULL DEFAULT 'planned'
                    CHECK (status IN ('planned', 'booked', 'completed', 'cancelled')),
    cost            numeric(12,2) NOT NULL DEFAULT 0 CHECK (cost >= 0),
    currency        char(3) NOT NULL DEFAULT 'USD',
    notes           text,
    version         integer NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    CHECK (end_time > start_time),
    UNIQUE (id, trip_id)
);
CREATE INDEX itinerary_items_trip_day_time_idx
    ON itinerary_items (trip_id, day, start_time);

CREATE TABLE bookings (
    id              uuid PRIMARY KEY,
    trip_id         uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    itinerary_item_id uuid,
    type            text NOT NULL,
    provider_ref    text,
    confirmation_no text,
    cancel_policy   text,
    starts_at       timestamptz,
    ends_at         timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (itinerary_item_id, trip_id)
        REFERENCES itinerary_items(id, trip_id) ON DELETE SET NULL (itinerary_item_id)
);
CREATE INDEX bookings_trip_idx ON bookings (trip_id);

-- Flights a trip wants to monitor. A provider adapter populates this table and
-- writes normalized updates to the flight inbox stream.
CREATE TABLE flight_subscriptions (
    id                  uuid PRIMARY KEY,
    trip_id             uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    provider            text NOT NULL,
    flight_number       text NOT NULL,
    scheduled_departure timestamptz NOT NULL,
    scheduled_arrival   timestamptz,
    trip_day            smallint NOT NULL DEFAULT 1 CHECK (trip_day > 0),
    origin              text,
    destination         text,
    status              text NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'cancelled', 'completed')),
    created_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (trip_id, provider, flight_number, scheduled_departure)
);
CREATE INDEX flight_subscriptions_lookup_idx
    ON flight_subscriptions (upper(flight_number), scheduled_departure)
    WHERE status = 'active';
ALTER TABLE itinerary_items
    ADD CONSTRAINT itinerary_items_flight_subscription_fk
    FOREIGN KEY (flight_subscription_id) REFERENCES flight_subscriptions(id) ON DELETE SET NULL;
CREATE INDEX itinerary_items_flight_subscription_idx
    ON itinerary_items (flight_subscription_id) WHERE flight_subscription_id IS NOT NULL;

CREATE TABLE alerts (
    id              uuid PRIMARY KEY,
    trip_id         uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    source          text NOT NULL,
    event_id        text,
    payload         jsonb NOT NULL DEFAULT '{}'::jsonb,
    suggested_change jsonb NOT NULL,
    status          text NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'accepted', 'dismissed', 'expired')),
    decided_by      uuid REFERENCES users(id) ON DELETE SET NULL,
    decided_at      timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (trip_id, source, event_id)
);
CREATE INDEX alerts_pending_trip_idx ON alerts (trip_id, created_at DESC)
    WHERE status = 'pending';

-- Event intake/idempotency ledger. Suggestions belong in alerts only after the
-- re-planning engine has produced an actual proposal for the traveler.
CREATE TABLE processed_events (
    trip_id         uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    source          text NOT NULL,
    event_id        text NOT NULL,
    payload         jsonb NOT NULL,
    processed_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (trip_id, source, event_id)
);

CREATE TABLE expenses (
    id              uuid PRIMARY KEY,
    trip_id         uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    user_id         uuid REFERENCES users(id) ON DELETE SET NULL,
    amount          numeric(12,2) NOT NULL CHECK (amount >= 0),
    currency        char(3) NOT NULL DEFAULT 'USD',
    category        text NOT NULL,
    description     text,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX expenses_trip_time_idx ON expenses (trip_id, occurred_at DESC);

-- Apply itinerary edits with optimistic concurrency:
-- UPDATE itinerary_items SET ..., version = version + 1, updated_at = now()
-- WHERE id = $1 AND trip_id = $2 AND version = $3;
-- A row count of zero means the client must fetch the latest version and resolve the conflict.
